def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    total = v1 + v2
    count = 2

    if count == 0:
        return None

    value = total / count

    return {
        "value": value,
        "trace": {
            "v1": v1,
            "v2": v2,
            "total": total,
            "count": count,
            "output_meta": {
                "currency": "USD",
                "scale": "thousands",
                "unit": "monetary"
            }
        }
    }
